package com.msb.ecom.payment_service.operations;
import com.msb.ecom.payment_service.config.PaymentOutboxProperties;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Clock;import java.util.List;
@Service
public class PaymentOperationsService {private final PaymentOperationsRepository repository;private final PaymentOutboxProperties outbox;private final Clock clock=Clock.systemUTC();public PaymentOperationsService(PaymentOperationsRepository repository,PaymentOutboxProperties outbox){this.repository=repository;this.outbox=outbox;}
 public PaymentOperationsContracts.Snapshot snapshot(){return new PaymentOperationsContracts.Snapshot("PAYMENT",true,"Payment operational signals loaded.",List.of(),repository.outbox(clock.instant(),outbox.maxAttempts()),repository.reconciliation(),List.of(),null,List.of(new PaymentOperationsContracts.Feature("PAYMENT_OUTBOX_DISPATCH","Payment outbox dispatch",outbox.enabled()&&outbox.workerEnabled()?"ENABLED":"DISABLED","SERVICE","Payment runtime configuration",null,false,"Dispatches payment terminal events through the existing bounded worker."),new PaymentOperationsContracts.Feature("REFUND_RECONCILIATION_RETRY","Automated refund reconciliation","UNAVAILABLE","SERVICE","Payment domain capability",null,false,"Refunds requiring attention are read-only because no safe provider recheck command exists.")));}
 @Transactional public PaymentOperationsContracts.Action action(PaymentOperationsContracts.ActionRequest r){if(r==null)throw new IllegalArgumentException("Action is required.");if(!"RETRY_OUTBOX".equals(r.commandType()))return unsupported(r);var event=repository.outbox(r.targetId(),clock.instant(),outbox.maxAttempts()).orElse(null);if(event==null)return unsupported(r);boolean allowed=event.retryable()&&outbox.enabled()&&outbox.workerEnabled();if(!r.dryRun()&&allowed)allowed=repository.retryOutbox(event.eventId(),clock.instant());return new PaymentOperationsContracts.Action("PAYMENT","OUTBOX_EVENT",event.eventId(),r.commandType(),event.status(),allowed,allowed?null:"OUTBOX_EVENT_NOT_RETRYABLE",List.of("Payment outbox dispatcher","Order payment-event deduplication"),List.of("A prior uncertain transport attempt may have reached the consumer."),"Schedule the existing event for dispatcher pickup.","Payment and refund state are not directly edited.",r.dryRun()?null:allowed?"ACCEPTED":"NOT_RETRYABLE",allowed?"Payment accepted the outbox retry request.":"The event is terminal, active, disabled, or otherwise not retryable.");}
 private PaymentOperationsContracts.Action unsupported(PaymentOperationsContracts.ActionRequest r){return new PaymentOperationsContracts.Action("PAYMENT",r.targetType(),r.targetId(),r.commandType(),"UNKNOWN",false,"SYSTEM_OPERATION_NOT_SUPPORTED",List.of(),List.of(),"No operation will run.","No payment state is changed.",r.dryRun()?null:"NOT_RETRYABLE","The Payment operation is unavailable.");}
}
